import unicodedata
import hashlib
import hmac
import os
import re
import time
from functools import wraps
from collections import defaultdict

# Rate limiter
class RateLimiter:
    def __init__(self, max_requests=100, window=60):
        self._counts = defaultdict(list)
        self._max = max_requests
        self._window = window

    def check(self, client_id):
        now = time.time()
        self._counts[client_id] = [
            t for t in self._counts[client_id] if now - t < self._window
        ]
        if len(self._counts[client_id]) >= self._max:
            return False
        self._counts[client_id].append(now)
        return True

# Session store with secure token generation
class SessionStore:
    def __init__(self):
        self._sessions = {}
        self._secret = os.urandom(32)

    def create_session(self, user_id, role):
        token = hashlib.sha256(os.urandom(32) + self._secret).hexdigest()
        self._sessions[token] = {
            'user_id': user_id,
            'role': role,
            'created': time.time(),
            'expires': time.time() + 3600
        }
        return token

    def validate_session(self, token):
        if not token or not isinstance(token, str):
            return None
        session = self._sessions.get(token)
        if session and session['expires'] > time.time():
            return session
        if session:
            del self._sessions[token]
        return None

    def destroy_session(self, token):
        self._sessions.pop(token, None)

# Access control policy engine
class PolicyEngine:
    def __init__(self):
        # Define which roles can access which path patterns
        self._policies = [
            {'pattern': r'^/public/.*$', 'roles': ['anonymous', 'user', 'admin']},
            {'pattern': r'^/user/profile$', 'roles': ['user', 'admin']},
            {'pattern': r'^/user/settings$', 'roles': ['user', 'admin']},
            {'pattern': r'^/admin/.*$', 'roles': ['admin']},
            {'pattern': r'^/api/data$', 'roles': ['user', 'admin']},
            {'pattern': r'^/internal/.*$', 'roles': []},  # No access
        ]
        self._default_deny = True

    def check_access(self, path, role):
        """Check if role has access to path. Uses first-match policy."""
        for policy in self._policies:
            if re.match(policy['pattern'], path):
                return role in policy['roles']
        return not self._default_deny

# Path sanitizer - removes traversal attempts
def sanitize_path_components(path):
    """Remove path traversal sequences and null bytes."""
    if not isinstance(path, str):
        return '/'
    # Remove null bytes
    path = path.replace('\x00', '')
    # Collapse multiple slashes
    path = re.sub(r'/+', '/', path)
    # Remove path traversal
    parts = path.split('/')
    clean_parts = []
    for part in parts:
        if part == '..':
            if clean_parts:
                clean_parts.pop()
        elif part == '.':
            continue
        else:
            clean_parts.append(part)
    result = '/' + '/'.join(clean_parts).strip('/')
    return result if result != '/' or path == '/' else result


class RequestHandler:
    def __init__(self):
        self.session_store = SessionStore()
        self.policy_engine = PolicyEngine()
        self.rate_limiter = RateLimiter()
        self._audit_log = []

    def _log_access(self, user_id, path, allowed):
        self._audit_log.append({
            'time': time.time(),
            'user': user_id,
            'path': path,
            'allowed': allowed
        })

    def handle_request(self, request):
        """Main request handler with full auth pipeline."""
        client_ip = request.get('client_ip', 'unknown')

        # Rate limiting
        if not self.rate_limiter.check(client_ip):
            return {'status': 429, 'body': 'Rate limited'}

        # Extract and validate session
        token = request.get('session_token')
        session = self.session_store.validate_session(token)
        role = session['role'] if session else 'anonymous'
        user_id = session['user_id'] if session else 'anonymous'

        # Get the requested path
        raw_path = request.get('path', '/')

        # Step 1: Sanitize path components (traversal protection)
        sanitized_path = sanitize_path_components(raw_path)

        # Step 2: Check authorization BEFORE normalization
        # This ensures the policy check sees the same path the user requested
        access_allowed = self.policy_engine.check_access(sanitized_path, role)

        # Step 3: Normalize Unicode for consistent storage/routing
        # NFC normalization combines characters (e.g., a\u0308 -> \u00e4)
        normalized_path = unicodedata.normalize('NFC', sanitized_path)

        self._log_access(user_id, normalized_path, access_allowed)

        if not access_allowed:
            return {'status': 403, 'body': 'Access denied'}

        # Route to handler based on normalized path
        return self._dispatch(normalized_path, session)

    def _dispatch(self, path, session):
        """Dispatch to appropriate handler based on normalized path."""
        if path.startswith('/admin/'):
            return self._handle_admin(path, session)
        elif path.startswith('/public/'):
            return self._handle_public(path)
        elif path.startswith('/user/'):
            return self._handle_user(path, session)
        elif path.startswith('/api/'):
            return self._handle_api(path, session)
        elif path.startswith('/internal/'):
            return self._handle_internal(path)
        return {'status': 404, 'body': 'Not found'}

    def _handle_admin(self, path, session):
        return {'status': 200, 'body': f'Admin panel: {path}'}

    def _handle_public(self, path):
        return {'status': 200, 'body': f'Public content: {path}'}

    def _handle_user(self, path, session):
        return {'status': 200, 'body': f'User area: {path}'}

    def _handle_api(self, path, session):
        return {'status': 200, 'body': f'API response: {path}'}

    def _handle_internal(self, path):
        return {'status': 200, 'body': f'Internal: {path}'}


